var mitrilSetup = (function(rawSetup) {
	function parseMixBoolean(value) {
		if (value === 'true') return true;
		if (value === 'false') return false;
		return parseInt(value);
	}
	var setup = {
		groups: {},
		items: {},
		functions: {},
		checkpoints: [],
		len: 67 ,
		ends: 5 ,
		prod: 1 ,
		index: 'skeptiki1',
		game_id: 10628
	};
	var groups = rawSetup['keywords'];
	if (groups) {
		for (var g = 0; g < groups.length; g++) {
			var group = groups[g];
			group.type = 'k';
			group.visible = parseMixBoolean(group.visible);
			group.limit = parseMixBoolean(group.limit);
			setup.groups[group.uid] = group;
			var items = group['items'];
			var list = [];
			if (items) {
				for (var i = 0; i < items.length; i++) {
					var item = items[i];
					item.group = group.uid;
					item.start = parseMixBoolean(item.start);
					item.limit = (item.limit && item.limit > 0) ? parseInt(item.limit) : 0;
					setup.items[item.uid] = item;
					list.push(item.uid);
				}
			}
			group.items = list;
		}
	}
	groups = rawSetup['resources'];
	if (groups) {
		for (var g = 0; g < groups.length; g++) {
			var group = groups[g];
			group.type = 'r';
			group.visible = parseMixBoolean(group.visible);
			group.limit = parseMixBoolean(group.limit);
			setup.groups[group.uid] = group;
			var items = group['items'];
			var list = [];
			if (items) {
				for (var i = 0; i < items.length; i++) {
					var item = items[i];
					item.group = group.uid;
					item.start = parseMixBoolean(item.start);
					setup.items[item.uid] = item;
					list.push(item.uid);
				}
			}
			group.items = list;
		}
	}

	if (rawSetup['functions']) {
		for (var f = 0; f < rawSetup['functions'].length; f++) {
			var func = rawSetup['functions'][f];
			setup.functions[func['func_uid']] = JSON.parse(func['func_script']);
		}
	}

	if (rawSetup['soundtrack']) {
		setup.soundtrack = {
			type: rawSetup['soundtrack']['type'],
			owner: rawSetup['soundtrack']['owner'],
			list: rawSetup['soundtrack']['list'],
			key: rawSetup['soundtrack']['key']
		};
	}
	if (rawSetup['checkpoints']) {
		setup.checkpoints = rawSetup['checkpoints'].slice();
	}

	rawSetup = undefined;
	return setup;
})({"keywords":[{"name":"\u0412\u044b\u0431\u043e\u0440 \u041f\u0430\u0448\u0438 - 1","uid":"4de6542c-b31f-4050-aef9-4c2e98bca9fb","visible":"false","limit":"false","items":[{"name":"\u0413\u0438\u0442\u0430\u0440\u0430","uid":"53e89b55-275d-4e79-a71c-d356088095e2","start":"false"},{"name":"\u0417\u0432\u043e\u043d\u043e\u043a","uid":"99f8c5e6-c571-4b99-b74a-9b89903ad94f","start":"false"},{"name":"\u0423\u0440\u043e\u043a","uid":"7fd930f7-714c-4429-9ca7-788920dcd458","start":"false"},{"name":"\u0421\u043f\u043e\u0440 \u0432 \u0441\u0435\u0442\u0438","uid":"c48e44a1-6225-4b98-b130-de7d4e25562b","start":"false"}]},{"name":"\u0412\u044b\u0431\u043e\u0440 \u041f\u0430\u0448\u0438-2","uid":"50f881d0-5f76-42e6-b63f-7b6fdc3e8f7f","visible":"false","limit":"false","items":[{"name":"\u0421\u043f\u0440\u043e\u0441\u0438\u043b \u043f\u0440\u043e \u0440\u0430\u0431\u043e\u0442\u0443","uid":"382f282f-1627-46b7-8732-6551bd0e7ba0","start":"false"},{"name":"\u0421\u043f\u0440\u043e\u0441\u0438\u043b \u043f\u0440\u043e \u043b\u0438\u0447\u043d\u0443\u044e \u0436\u0438\u0437\u043d\u044c","uid":"0c6fa003-bab4-4cd0-9b2c-dccd2842485b","start":"false"},{"name":"\u0421\u043f\u0440\u043e\u0441\u0438\u043b \u043f\u0440\u043e \u043e\u0442\u043f\u0443\u0441\u043a","uid":"db6ff7a6-7780-4fa9-844b-990b16a5abad","start":"false"}]},{"name":"\u0421\u044e\u0436\u0435\u0442\u043d\u044b\u0435 \u0441\u043e\u0431\u044b\u0442\u0438\u044f","uid":"db63f94d-10fa-4c73-8c72-239c4adf6d78","visible":"false","limit":"false","items":[{"name":"\u0414\u0443\u0440\u0430\u0446\u043a\u0430\u044f \u0448\u0443\u0442\u043a\u0430","uid":"25a4cbe7-7e35-4f15-8da5-a62f1609272a","start":"false"},{"name":"\u0410\u043d\u0435\u043a\u0434\u043e\u0442","uid":"ca0799eb-0360-4a4b-9a76-acd18d95438a","start":"false"}]},{"name":"\u0423\u043b\u0438\u043a\u0438-1","uid":"832c2579-dfb1-4232-acf2-128904757a9b","visible":"false","limit":"false","items":[{"name":"\u0410\u043d\u043e\u043c\u0430\u043b\u0438\u044f","uid":"03f6dff6-2225-4504-ae4